pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount, uint256 extra, address receiver) public {
        // wide admissible domain: any receiver, any amount, strictly positive surplus
        vm.assume(receiver != address(0));
        vm.assume(receiver != address(c));
        extra = bound(extra, 1, 1 ether);
        amount = bound(amount, 0, 1 ether);

        // contract holds amount + extra (> amount), so a correct transfer sends exactly `amount`
        vm.deal(address(c), amount + extra);

        uint256 recvBefore = receiver.balance;

        vm.prank(address(this)); // owner (deployer) is the test contract
        c.sendTo(receiver, amount);

        uint256 recvAfter = receiver.balance;

        // RULE: the receiver gains exactly `amount` — for every admissible input.
        // The mutant sends address(this).balance = amount + extra > amount, breaking it.
        assertTrue(recvAfter - recvBefore == amount);
    }
}

