pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint256).max - 1);
        // Fund the contract with strictly more than `amount`.
        vm.deal(address(c), amount + 1);
        // Adversarial receiver that accepts exactly `amount` wei and nothing else.
        StrictReceiver r = new StrictReceiver(amount);

        vm.prank(address(this)); // deployer is owner of c
        bool ok;
        try c.sendTo(payable(address(r)), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference C always transfers exactly `amount`, so the strict receiver accepts: ok is true.
        // The mutant transfers the whole balance (amount+1 != amount), so the receiver rejects and the call reverts.
        assertTrue(ok);
    }
}

contract StrictReceiver {
    uint256 demanded;
    constructor(uint256 d) { demanded = d; }
    receive() external payable {
        require(msg.value == demanded, "wrong value");
    }
}

