pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address receiver, uint256 amount) public {
        // Admissible domain: non-owner caller, strictly positive amount.
        // c is deployed with 0 ether, so any amount >= 1 makes the transfer itself fail.
        vm.assume(caller != address(this)); // owner is the deployer (this test contract)
        bound(amount, 1, type(uint128).max);

        vm.deal(address(c), 0); // contract holds no ether: transfer(amount>=1) throws Panic(0x12)
        vm.prank(caller);

        bool panicked = false;
        try c.sendTo(receiver, amount) {
            // should not happen for a non-owner
        } catch Panic(uint256) {
            panicked = true;
        } catch {
            panicked = false;
        }

        // General rule: a non-owner call reverts cleanly (empty require revert),
        // it never leaks a Panic(0x12) from an executed transfer.
        assertTrue(!panicked);
    }
}

