pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 beforeBal;

    function setUp() public { c = new C(); }

    // This test contract is the owner (msg.sender in setUp) and doubles as the
    // re-entrant receiver: during the transfer it checks that c's balance has
    // not changed yet, i.e. that the transfer happens only after validation.
    receive() external payable {
        if (address(c).balance != beforeBal) revert();
    }

    function testFuzz_property(uint256 amount) public {
        // 1. wide admissible domain: any transferable amount the contract can hold
        amount = bound(amount, 1, type(uint96).max);
        vm.deal(address(c), amount);

        // 2. drive c through sendTo as the owner, paying ourselves so the
        //    re-entrant receive() fires during the transfer
        beforeBal = address(c).balance;
        bool ok;
        try c.sendTo(address(this), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // 3. rule: a validated (owner) transfer must not move funds out of c
        //    before it is issued, so the re-entrant receiver sees an unchanged
        //    balance and the call succeeds. The mutant transfers first, the
        //    receiver observes the reduced balance, reverts, and the call fails.
        assertTrue(ok, "owner sendTo to re-entrant receiver must succeed with balance intact during transfer");
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function f(address r1, address r2) public {
        require(r1 != address(this) && r2 != address(this) && r1 != r2);

        // First call succeeds because this contract is the owner of c.
        c.sendTo(r1, 0);

        // In P the owner is unchanged, so this second call must also succeed.
        // In M the first call set owner = r1, so this second call reverts.
        bool ok2 = true;
        try c.sendTo(r2, 0) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assert(ok2);
    }
}

